/**
 * Cover spread geometry for perfect-bound products.
 *
 * Pure, DOM-free planning for the two wide cover sheets a printer expects when a
 * book has a spine: the OUTER sheet (back cover · spine · front cover) and the
 * INNER sheet (inside front · blank spine + glue zones · inside back). The DOM
 * layer (`Static.CoverSpread`, `PageEditor`) and `PageSizeUtils` only consume the
 * numbers produced here, so the printer-facing contract can be unit-tested with
 * `node --test` against approved PDF sizes.
 *
 * All values are millimetres. See docs/printer-cover-spine-support.md.
 *
 * @typedef {'perfect' | 'saddle'} BindingType
 *
 * @typedef {Object} BindingConfig
 * @property {BindingType} [type]  Defaults to 'perfect' when spine > 0.
 * @property {number} spine        Spine width. The printer supplies this number.
 * @property {number} [glue]       Ink-free margin on each side of the spine, inner sheet only.
 *
 * @typedef {Object} ResolvedBinding
 * @property {'perfect'} type
 * @property {number} spine
 * @property {number} glue
 *
 * @typedef {Object} Box
 * @property {number} x
 * @property {number} y
 * @property {number} width
 * @property {number} height
 *
 * @typedef {'outer' | 'inner'} CoverSheetKind
 * @typedef {'left' | 'right'} PanelSide
 */

const MAX_BLEED = 400;

function toFiniteNumber(value) {
  const numeric = typeof value === 'string' && value.trim() !== '' ? Number(value) : value;
  return typeof numeric === 'number' && Number.isFinite(numeric) ? numeric : null;
}

/** Trim floating point noise (e.g. 104.8 + 15) so CSS values stay readable. */
function round(value) {
  return Math.round(value * 10000) / 10000;
}

/**
 * Normalise a `binding` declaration. Returns `null` whenever no spread should be
 * composed: binding absent, `type: 'saddle'`, or a non-positive spine.
 *
 * @param {BindingConfig | null | undefined} binding
 * @returns {ResolvedBinding | null}
 */
export function resolveBinding(binding) {
  if (!binding || typeof binding !== 'object') return null;
  if (binding.type === 'saddle') return null;

  const spine = toFiniteNumber(binding.spine);
  if (spine === null || spine <= 0) return null;

  const glue = toFiniteNumber(binding.glue);

  return {
    type: 'perfect',
    spine: round(spine),
    glue: glue === null || glue < 0 ? 0 : round(glue),
  };
}

/**
 * Normalise the page geometry shared by every planner below.
 *
 * @param {{ width?: number, height?: number, bleed?: number }} input
 * @returns {{ width: number, height: number, bleed: number } | null}
 */
function resolvePage(input = {}) {
  const width = toFiniteNumber(input.width);
  const height = toFiniteNumber(input.height);
  if (width === null || height === null || width <= 0 || height <= 0) return null;

  const bleed = toFiniteNumber(input.bleed);
  return {
    width: round(width),
    height: round(height),
    bleed: bleed === null ? 0 : round(Math.min(Math.max(bleed, 0), MAX_BLEED)),
  };
}

/**
 * The physical sheet the PDF page must have, with bleed included.
 *
 * Without an active binding this is the ordinary single page (`W + 2B × H + 2B`),
 * so `PageSizeUtils` can call it unconditionally to fill `--uhuu-sheet-*`.
 * With a spine it is the wide cover sheet: `2W + S + 2B × H + 2B`.
 *
 * @param {{ width?: number, height?: number, bleed?: number, binding?: BindingConfig | null }} input
 * @returns {{ width: number, height: number, trimWidth: number, trimHeight: number, spread: boolean } | null}
 */
export function resolveSheetSize(input = {}) {
  const page = resolvePage(input);
  if (!page) return null;

  const binding = resolveBinding(input.binding);
  const trimWidth = binding ? page.width * 2 + binding.spine : page.width;
  const trimHeight = page.height;

  return {
    trimWidth: round(trimWidth),
    trimHeight: round(trimHeight),
    width: round(trimWidth + page.bleed * 2),
    height: round(trimHeight + page.bleed * 2),
    spread: !!binding,
  };
}

/**
 * Cover pages come out of the `cover` page filter in document order:
 * `[p1, p2, p(n-1), p(n)]` for `coverPageCount: 2` or `[p1, p(n)]` for
 * `coverPageCount: 1`. Map them onto sheets, printer reading order:
 *
 *   outer: left = back cover (last), right = front cover (first)
 *   inner: left = inside front (second), right = inside back (second to last)
 *
 * @template TPage
 * @param {TPage[]} coverPages
 * @returns {Array<{ sheet: CoverSheetKind, left: TPage, right: TPage }> | null}
 */
export function assignCoverPages(coverPages) {
  if (!Array.isArray(coverPages)) return null;

  if (coverPages.length === 2) {
    return [{ sheet: 'outer', left: coverPages[1], right: coverPages[0] }];
  }

  if (coverPages.length === 4) {
    return [
      { sheet: 'outer', left: coverPages[3], right: coverPages[0] },
      { sheet: 'inner', left: coverPages[1], right: coverPages[2] },
    ];
  }

  return null;
}

/**
 * Plan the cover sheets for a perfect-bound product.
 *
 * Returns `null` when no spread applies (no binding / saddle stitch / bad page
 * size / unsupported cover page count) so callers fall back to plain cover pages.
 *
 * Coordinates are relative to the top-left of the sheet INCLUDING bleed.
 *
 * @template TPage
 * @param {{
 *   width?: number,
 *   height?: number,
 *   bleed?: number,
 *   binding?: BindingConfig | null,
 *   coverPages?: TPage[],
 * }} input
 * @returns {{
 *   binding: ResolvedBinding,
 *   page: { width: number, height: number, bleed: number },
 *   sheet: { width: number, height: number, trimWidth: number, trimHeight: number },
 *   sheets: Array<{
 *     sheet: CoverSheetKind,
 *     index: number,
 *     panels: Array<{ side: PanelSide, page: TPage, trim: Box, bleedBox: Box }>,
 *     spine: Box & { blank: boolean },
 *     glueZones: Array<Box & { side: PanelSide }>,
 *   }>,
 * } | null}
 */
export function planCoverSpread(input = {}) {
  const page = resolvePage(input);
  const binding = resolveBinding(input.binding);
  const assignment = assignCoverPages(input.coverPages);
  if (!page || !binding || !assignment) return null;

  const { width: W, height: H, bleed: B } = page;
  const { spine: S, glue: G } = binding;
  const sheetHeight = round(H + B * 2);
  const sheetTrimWidth = round(W * 2 + S);
  const sheetWidth = round(sheetTrimWidth + B * 2);

  const spineX = round(B + W);
  const rightTrimX = round(B + W + S);

  const leftPanel = (pageRef) => ({
    side: 'left',
    page: pageRef,
    trim: { x: B, y: B, width: W, height: H },
    // Outer bleed on top/left/bottom only; the panel is cut at the spine.
    bleedBox: { x: 0, y: 0, width: round(B + W), height: sheetHeight },
  });

  const rightPanel = (pageRef) => ({
    side: 'right',
    page: pageRef,
    trim: { x: rightTrimX, y: B, width: W, height: H },
    bleedBox: { x: rightTrimX, y: 0, width: round(W + B), height: sheetHeight },
  });

  const sheets = assignment.map((entry, index) => {
    const inner = entry.sheet === 'inner';
    const glueZones = inner && G > 0
      ? [
          { side: 'left', x: round(spineX - G), y: 0, width: G, height: sheetHeight },
          { side: 'right', x: rightTrimX, y: 0, width: G, height: sheetHeight },
        ]
      : [];

    return {
      sheet: entry.sheet,
      index,
      panels: [leftPanel(entry.left), rightPanel(entry.right)],
      spine: { x: spineX, y: 0, width: S, height: sheetHeight, blank: inner },
      glueZones,
    };
  });

  return {
    binding,
    page,
    sheet: { width: sheetWidth, height: sheetHeight, trimWidth: sheetTrimWidth, trimHeight: H },
    sheets,
  };
}

/**
 * CSS custom properties for the root element. Always returns the four sheet
 * variables so a previous spread never leaks into a plain render.
 *
 * @param {{ width?: number, height?: number, bleed?: number, binding?: BindingConfig | null }} input
 * @returns {Record<'--uhuu-sheet-width' | '--uhuu-sheet-height' | '--uhuu-spine-width' | '--uhuu-glue-width', string> | null}
 */
export function coverSpreadCssVars(input = {}) {
  const sheet = resolveSheetSize(input);
  if (!sheet) return null;

  const binding = resolveBinding(input.binding);
  return {
    '--uhuu-sheet-width': `${sheet.width}mm`,
    '--uhuu-sheet-height': `${sheet.height}mm`,
    '--uhuu-spine-width': `${binding ? binding.spine : 0}mm`,
    '--uhuu-glue-width': `${binding ? binding.glue : 0}mm`,
  };
}

/**
 * Developer-facing sanity checks. Returns human readable warnings; an empty
 * array means the configuration is printable as declared.
 *
 * @param {{
 *   width?: number,
 *   height?: number,
 *   bleed?: number,
 *   binding?: BindingConfig | null,
 *   coverPageCount?: number,
 *   coverPages?: unknown[],
 *   preview?: string,
 *   flowCoverPages?: number,
 * }} input
 * @returns {string[]}
 */
export function getCoverSpreadWarnings(input = {}) {
  const binding = resolveBinding(input.binding);
  if (!binding) return [];

  const warnings = [];
  const page = resolvePage(input);
  const coverPageCount = toFiniteNumber(input.coverPageCount);

  if (!page) {
    warnings.push('binding.spine is set but the page format has no valid width/height; cover spread skipped.');
  }

  if (coverPageCount !== null && coverPageCount !== 1 && coverPageCount !== 2) {
    warnings.push(
      `binding.spine is set but pageFilter.coverPageCount is ${coverPageCount}; a cover spread needs 1 (outer sheet only) or 2 (outer + inner). Rendering plain cover pages.`
    );
  }

  if (Array.isArray(input.coverPages) && !assignCoverPages(input.coverPages)) {
    warnings.push(
      `binding.spine is set but the cover filter produced ${input.coverPages.length} page(s); a cover spread needs 2 or 4. Rendering plain cover pages.`
    );
  }

  if (page && binding.glue > 0 && binding.glue >= page.width / 2) {
    warnings.push(
      `binding.glue (${binding.glue}mm) is at least half the page width (${page.width}mm); the glue mask would hide most of the inside covers.`
    );
  }

  if (page && page.bleed > 0 && binding.spine < page.bleed) {
    warnings.push(
      `binding.spine (${binding.spine}mm) is narrower than the bleed (${page.bleed}mm); panels are cut at the spine, so artwork will not run across it unless the spine component paints it.`
    );
  }

  if (input.preview === 'two_pages') {
    warnings.push('preview "two_pages" is ignored while a cover spread is active; each sheet is already a spread.');
  }

  if (toFiniteNumber(input.flowCoverPages) > 0) {
    warnings.push('a cover page has hasFlow: true; only its first chunk is placed on the cover sheet.');
  }

  return warnings;
}
